    H,W=len(I),len(I[0]); O=[row[:] for row in I]
    for c in range(W):
        seeds=[(r,I[r][c]) for r in range(H) if I[r][c]]
        if not seeds: continue
        v0=seeds[0]; 
        for r in range(v0[0]): O[r][c]=v0[1]      # above topmost seed: fill upward
        for i in range(len(seeds)-1):
            (ra,va),(rb,vb)=seeds[i],seeds[i+1]
            for r in range(ra[0]+1,rb[0]): O[r][c]=vb    # between seeds: lower one's color
    return O
